-- Research stage gates in the database, a stage history for the Live Enrichment dashboard, and a
-- resumable editorial job that writes original signposting summaries and fills missing fields with
-- evidence. GENERATED by scripts/build-research-editorial-migration.mjs from this template and
-- scripts/research-stage-assessment.sql; edit those, then regenerate.

-- 1. Placeholder and scraped-page summaries are not summaries. "Stage 2 source inventory record" text
--    slipped past the previous pattern, as did whole-page markdown captures and copied abstracts.
create or replace function public.research_clean_summary(value text) returns text language sql immutable strict set search_path='' as $$
 select case when value ~* 'Stage [0-9]+ (source )?inventory record|Item.level review has not yet been performed|Login or Register for Access|Username\(Required\).*Password|Hit enter to search or ESC to close'
 or value ~ '^\s*\[Skip to content\]'
 or value ~* '^\s*#{1,4} *(Purpose|Background|Abstract|Objectives?|Aims?|Introduction|Context)\s'
 or btrim(value) in (
 'Publisher-listed resource. Metadata recorded for discovery; independent evidence appraisal pending.',
 'Public repository metadata entry. Eligibility and the underlying publication have not been verified.',
 'Resource identified in the official source listing. Content and evidence have not yet been independently appraised.'
 ) then ''
 else left(regexp_replace(regexp_replace(value,'<[^>]*>',' ','g'),'[[:space:]]+',' ','g'),3000) end;
$$;

-- 2. The stage gates, identical to scripts/research-stage-assessment.sql (a test enforces this).
create or replace function private.research_stage_rows(p_reviews jsonb default '{}'::jsonb, p_reviewed_only boolean default false)
returns table(id text, stage integer, fingerprint text, url text, ready_for_review boolean,
  stage4_blockers text[], stage5_blockers text[], publication_evidence text, checks jsonb,
  supplied jsonb, reviewed jsonb)
language sql stable set search_path='' as $fn$
with reviews as (
  select key id,value review from jsonb_each(p_reviews)
), assurance as (
  select * from private.enrichment_dashboard_assurance()
), duplicates as (
  select distinct unnest(record_ids) record_id from private.research_duplicate_review
  where review_status='unreviewed'
), documents as (
  select r.id,r.title,r.url,r.authors,r.year,r.source,r.summary,r.tags,r.kind_std,
    md5((to_jsonb(r)-'search_vector')::text) fingerprint,
    a.assessment_status,a.assessed_at,a.checks,a.baseline_fingerprint,a.reported_at,
    (s.id is not null) source_published,
    (sd.content_hash=md5(left(concat_ws('. ',r.title,
      nullif(array_to_string(r.tags,', '),''),nullif(r.related_terms,''),
      nullif(public.research_clean_summary(r.summary),'')),1600))
      and sd.title_text=public.research_normalise(r.title)) is true indexed,
    coalesce(
      case when d.status='verified' and lower(btrim(r.doi))=lower(btrim(d.doi))
        and d.evidence_url ~ '^https?://[^[:space:]/]+' then d.evidence_url end,
      case when q.publisher_status='verified' and q.publisher_evidence_url ~ '^https?://[^[:space:]/]+'
        and (regexp_replace(q.publisher_evidence_url,'/$','')=regexp_replace(r.url,'/$','')
             or q.publisher_metadata->>'source_url'=r.url)
        then q.publisher_evidence_url end,
      case when q.status='verified' and q.evidence_url ~ '^https?://[^[:space:]/]+'
        and public.research_normalise(q.metadata->>'title')=public.research_normalise(r.title)
        then q.evidence_url end
    ) publication_evidence,
    (du.record_id is not null) duplicate_open,
    (d.status='verified' and nullif(btrim(d.evidence_url),'') is not null
      or q.status='verified' and nullif(btrim(q.evidence_url),'') is not null
      or q.publisher_status='verified' and nullif(btrim(q.publisher_evidence_url),'') is not null) is true confirmed,
    v.review supplied
  from public.research_records r
  left join public.sources s on s.slug=r.source_slug and s.status='published'
  left join public.research_search_documents sd on sd.record_id=r.id
  left join private.doi_enrichment_queue d on d.record_id=r.id
  left join private.non_doi_enrichment_queue q on q.record_id=r.id
  left join assurance a on a.record_id=r.id
  left join duplicates du on du.record_id=r.id
  left join reviews v on v.id=r.id
  where (not p_reviewed_only or v.id is not null)
), evidence as (
  select *,
    case when supplied->>'fingerprint'=fingerprint then supplied
         when checks#>>'{stage4_review,fingerprint}'=fingerprint then checks->'stage4_review'
    end reviewed,
    (assessment_status in ('automatic_screened','evidence_verified')) is true screened
  from documents
), gaps as (
  select *,array_remove(array[
    case when not screened then 'screening_pending' end,
    case when not confirmed then 'publication_confirmation_pending'
      when publication_evidence is null then 'publication_evidence_requires_recheck' end,
    case when coalesce(btrim(title),'')='' then 'title_missing' end,
    case when btrim(coalesce(authors,'')) ~* '^(|not stated.*|not specified.*|unknown.*|responsible organisation:.*|n/a|none listed.*|none|editor|editors|anonymous|various)$' then 'author_or_organisation_missing' end,
    case when year is null and not (
      coalesce(kind_std in ('not-research','publication-resource-page','information-webpage','nonpaper-resource'),false)
      and nullif(btrim(reviewed#>>'{year_not_applicable,reason}'),'') is not null
    ) then 'publication_year_missing' end,
    case when not source_published or coalesce(btrim(source),'')='' then 'source_attribution_unresolved' end,
    case when coalesce(public.research_clean_summary(summary),'')='' then 'summary_missing' end,
    case when not exists(select from unnest(tags) tag where btrim(tag)<>'') then 'topics_missing' end,
    case when coalesce(url,'') !~ '^https?://[^[:space:]/]+' then 'research_link_missing' end,
    case when reviewed is null then 'current_field_evidence_required' end,
    case when supplied is not null and supplied->>'fingerprint' is distinct from fingerprint then 'review_snapshot_changed' end
  ],null) stage4_blockers
  from evidence
), decisions as (
  select *,
    (cardinality(stage4_blockers)=0) ready_for_review,
    array_remove(array[
      case when reported_at is not null then 'open_assurance_issue' end,
      case when duplicate_open then 'duplicate_review_pending' end,
      case when not indexed then 'search_index_pending' end,
      case when jsonb_typeof(reviewed->'final') is distinct from 'object' then 'final_review_required' end,
      case when reviewed ? 'final' and reviewed#>>'{final,checked_url}' is distinct from url
        then 'link_check_is_for_another_url' end,
      case when (coalesce(supplied->>'live_found','false')<>'true') then 'live_search_confirmation_required' end
    ],null) stage5_blockers
  from gaps
), assessment as (
  select *,case
    when ready_for_review and assessment_status='evidence_verified'
      and checks->'full_record_verified'='true'::jsonb and baseline_fingerprint=fingerprint
      and reported_at is null and not duplicate_open and indexed then 5
    when ready_for_review then 4
    when screened and confirmed then 3
    when screened then 2
    else 1 end stage
  from decisions
)
select id,stage,fingerprint,url,ready_for_review,stage4_blockers,stage5_blockers,
  publication_evidence,checks,supplied,reviewed from assessment
$fn$;
revoke all on function private.research_stage_rows(jsonb,boolean) from public, anon, authenticated;

-- 3. Record reviews exactly as the runner's --apply does (Stage 4 evidence, or Stage 5 sign-off).
create or replace function private.research_stage_apply(p_reviews jsonb) returns jsonb
language plpgsql set search_path='' as $fn$
declare result jsonb;
begin
  if jsonb_typeof(p_reviews) is distinct from 'object' then raise exception 'reviews must be an object keyed by record ID'; end if;
  perform pg_advisory_xact_lock(68130921);
  perform 1 from public.research_records r where r.id in (select key from jsonb_each(p_reviews)) order by r.id for update;
  with selected as materialized (
    select a.*, (cardinality(a.stage5_blockers)=0 and a.reviewed#>>'{final,checked_url}'=a.url) approved
    from private.research_stage_rows(p_reviews,true) a
    where a.supplied is not null and a.ready_for_review and a.stage<5
      and (cardinality(a.stage5_blockers)=0 and a.reviewed#>>'{final,checked_url}'=a.url
        or a.supplied-'live_found' is distinct from a.checks->'stage4_review')
  ), new_batch as (
    insert into private.verification_batches(programme_id,batch_number,status,target_count,rules_version,
      started_at,completed_at,checkpoint_at,summary)
    select p.id,coalesce((select max(b.batch_number) from private.verification_batches b where b.programme_id=p.id),0)+1,
      'assessed',count(*)::int,'research-stage-gates-v1',now(),now(),now(),
      jsonb_build_object('stage4',count(*) filter(where approved is not true),
                         'stage5',count(*) filter(where approved is true))
    from selected cross join private.verification_programmes p
    where p.name='ID-EBP catalogue assurance baseline 2026-11' and p.status='active' group by p.id
    returning id
  ), stamped as (
    insert into private.verification_items(batch_id,record_id,baseline_record,baseline_fingerprint,
      selected_reason,assessment_status,checks,assessed_at)
    select b.id,m.id,to_jsonb(r)-'search_vector',m.fingerprint,'reviewed research stage evidence',
      case when m.approved then 'evidence_verified' else 'automatic_screened' end,
      coalesce(m.checks,'{}'::jsonb)||jsonb_build_object('stage4_review',m.supplied-'live_found',
        'publication_evidence',m.publication_evidence,'full_record_verified',m.approved is true,
        'live_search_verified_at',case when m.approved then now() end),
      now()
    from selected m join public.research_records r on r.id=m.id cross join new_batch b
    returning assessment_status
  ) select jsonb_build_object('stage4_recorded',count(*) filter(where assessment_status='automatic_screened'),
      'stage5_signed_off',count(*) filter(where assessment_status='evidence_verified')) into result from stamped;
  return result;
end;
$fn$;
revoke all on function private.research_stage_apply(jsonb) from public, anon, authenticated;

-- 4. Stage history: current stage per record and every observed change. Counts before the first
--    snapshot are not reconstructed; the dashboard reports the first snapshot as its reliable start.
create table if not exists private.research_stage_state (
  record_id text primary key,
  stage integer not null check (stage between 1 and 5),
  changed_at timestamptz not null default now(),
  observed_at timestamptz not null default now()
);
create table if not exists private.research_stage_transitions (
  id bigint generated always as identity primary key,
  record_id text not null,
  from_stage integer check (from_stage between 1 and 5),
  to_stage integer not null check (to_stage between 1 and 5),
  changed_at timestamptz not null default now(),
  note text
);
create index if not exists research_stage_transitions_time on private.research_stage_transitions(changed_at desc);
create table if not exists private.research_stage_snapshots (
  taken_at timestamptz primary key default now(),
  total integer not null,
  counts jsonb not null,
  blockers jsonb not null
);
alter table private.research_stage_state enable row level security;
alter table private.research_stage_transitions enable row level security;
alter table private.research_stage_snapshots enable row level security;
revoke all on private.research_stage_state, private.research_stage_transitions, private.research_stage_snapshots
  from public, anon, authenticated;

create or replace function private.refresh_research_stage_state(p_note text default null) returns jsonb
language plpgsql set search_path='' as $fn$
declare snap private.research_stage_snapshots;
begin
  if not pg_try_advisory_xact_lock(68130922) then return jsonb_build_object('status','busy'); end if;
  create temporary table if not exists pg_temp.stage_now(record_id text primary key, stage int, b4 text[], b5 text[]) on commit drop;
  truncate pg_temp.stage_now;
  insert into pg_temp.stage_now select a.id,a.stage,a.stage4_blockers,a.stage5_blockers from private.research_stage_rows() a;
  insert into private.research_stage_transitions(record_id,from_stage,to_stage,note)
  select n.record_id,s.stage,n.stage,coalesce(p_note,'hourly stage refresh')
  from pg_temp.stage_now n left join private.research_stage_state s on s.record_id=n.record_id
  where s.stage is distinct from n.stage and s.record_id is not null;
  insert into private.research_stage_state(record_id,stage,changed_at,observed_at)
  select record_id,stage,now(),now() from pg_temp.stage_now
  on conflict (record_id) do update set changed_at=now(), stage=excluded.stage, observed_at=now()
    where private.research_stage_state.stage<>excluded.stage;
  delete from private.research_stage_state s where not exists (select from pg_temp.stage_now n where n.record_id=s.record_id);
  insert into private.research_stage_snapshots(taken_at,total,counts,blockers)
  select now(),count(*),
    (select jsonb_object_agg(g::text,(select count(*) from pg_temp.stage_now x where x.stage=g)) from generate_series(1,5) g),
    (select coalesce(jsonb_object_agg(reason,n),'{}'::jsonb) from (
      select reason,count(*) n from pg_temp.stage_now cross join lateral
        unnest(case when stage<4 then b4 else b5 end) reason where stage<5 group by reason) z)
  from pg_temp.stage_now
  on conflict (taken_at) do nothing
  returning * into snap;
  return to_jsonb(snap);
end;
$fn$;
revoke all on function private.refresh_research_stage_state(text) from public, anon, authenticated;

-- 5. Editorial job: queue, run log and per-field evidence (append-only).
create table if not exists private.research_editorial_runs (
  id uuid primary key default gen_random_uuid(),
  started_at timestamptz not null default now(),
  lease_until timestamptz not null,
  finished_at timestamptz,
  reviewer text not null,
  claimed integer not null default 0,
  written integer not null default 0,
  filled integer not null default 0,
  held integer not null default 0,
  stale integer not null default 0,
  stage4_recorded integer not null default 0,
  signed_off integer not null default 0,
  note text
);
create table if not exists private.research_editorial_queue (
  record_id text primary key,
  reasons text[] not null,
  priority integer not null,
  status text not null default 'queued' check (status in ('queued','claimed','done','held')),
  run_id uuid references private.research_editorial_runs(id),
  claimed_until timestamptz,
  attempts integer not null default 0,
  claim_fingerprint text,
  held_reason text,
  note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (status <> 'held' or nullif(btrim(held_reason),'') is not null)
);
create index if not exists research_editorial_queue_next on private.research_editorial_queue(status, priority, record_id);
create table if not exists private.research_field_evidence (
  id bigint generated always as identity primary key,
  record_id text not null,
  field text not null check (field in ('title','authors','year','source','summary','tags','url')),
  action text not null check (action in ('confirmed','filled','written','replaced')),
  evidence_url text not null check (evidence_url ~ '^https?://[^[:space:]/]+' and length(evidence_url)<=2048),
  record_fingerprint text not null,
  reviewer text not null,
  run_id uuid references private.research_editorial_runs(id),
  previous_value text,
  note text,
  recorded_at timestamptz not null default now()
);
create index if not exists research_field_evidence_record on private.research_field_evidence(record_id, recorded_at desc);
alter table private.research_editorial_runs enable row level security;
alter table private.research_editorial_queue enable row level security;
alter table private.research_field_evidence enable row level security;
revoke all on private.research_editorial_runs, private.research_editorial_queue, private.research_field_evidence
  from public, anon, authenticated;
create or replace function private.refuse_evidence_change() returns trigger language plpgsql set search_path='' as $fn$
begin raise exception 'research_field_evidence is append-only'; end; $fn$;
drop trigger if exists research_field_evidence_append_only on private.research_field_evidence;
create trigger research_field_evidence_append_only before update or delete on private.research_field_evidence
  for each row execute function private.refuse_evidence_change();
drop trigger if exists research_field_evidence_no_truncate on private.research_field_evidence;
create trigger research_field_evidence_no_truncate before truncate on private.research_field_evidence
  for each statement execute function private.refuse_evidence_change();

create or replace function private.research_author_missing(value text) returns boolean
language sql immutable set search_path='' as $fn$
  select btrim(coalesce(value,'')) ~* '^(|not stated.*|not specified.*|unknown.*|responsible organisation:.*|n/a|none listed.*|none|editor|editors|anonymous|various)$'
$fn$;

-- Only an empty value or a pure placeholder may be filled. Organisation labels such as
-- "Responsible organisation: Home Office", "Anonymous" or "Various" are kept and need human review.
create or replace function private.research_author_fillable(value text) returns boolean
language sql immutable set search_path='' as $fn$
  select btrim(coalesce(value,'')) ~* '^(|not stated|not specified|n/a|none listed|none|unknown)$'
$fn$;
create or replace function private.research_words(value text) returns text
language sql immutable set search_path='' as $fn$
  select btrim(regexp_replace(lower(coalesce(value,'')),'[^[:alnum:]]+',' ','g'))
$fn$;
-- True when the draft shares a run of ten or more consecutive words with the given text.
create or replace function private.research_shares_run(draft text, source text) returns boolean
language sql immutable set search_path='' as $fn$
  with w as (select regexp_split_to_array(private.research_words(draft),' ') a, ' '||private.research_words(source)||' ' b)
  select exists(select from w, generate_series(1,greatest(cardinality(w.a)-9,0)) i
    where position(' '||array_to_string(w.a[i:i+9],' ')||' ' in w.b)>0)
$fn$;

-- Seeds (and tops up) the queue from the live gates. Idempotent: done/held rows are left alone,
-- except held "evidence unreachable" rows, which return after three days (at most three attempts).
create or replace function private.research_editorial_seed() returns jsonb
language plpgsql set search_path='' as $fn$
declare added integer; requeued integer;
begin
  perform pg_advisory_xact_lock(68130923);
  with needs as (
    select a.id, array_remove(array[
        case when 'summary_missing'=any(a.stage4_blockers) then 'summary_missing' end,
        case when 'author_or_organisation_missing'=any(a.stage4_blockers) then 'author_missing' end,
        case when 'publication_year_missing'=any(a.stage4_blockers) then 'year_missing' end,
        case when 'topics_missing'=any(a.stage4_blockers) then 'topics_missing' end,
        case when 'current_field_evidence_required'=any(a.stage4_blockers) then 'field_evidence' end],null) reasons,
      a.stage,
      cardinality(array(select unnest(a.stage4_blockers) except select unnest(array['summary_missing',
        'author_or_organisation_missing','publication_year_missing','topics_missing','current_field_evidence_required']))) other
    from private.research_stage_rows() a where a.stage in (2,3)
  )
  insert into private.research_editorial_queue(record_id,reasons,priority)
  select id,reasons,(case when stage=3 and other=0 then 0 when stage=3 then 1 else 2 end)*10
    + case when 'summary_missing'=any(reasons) then 0 else 1 end
  from needs where cardinality(reasons)>0
  on conflict (record_id) do update set reasons=excluded.reasons,priority=excluded.priority,updated_at=now()
    where private.research_editorial_queue.status='queued';
  get diagnostics added = row_count;
  -- Done rows the gates still block on editorial grounds (partly fixed, or changed since) come back daily.
  update private.research_editorial_queue q set status='queued',run_id=null,claimed_until=null,updated_at=now(),
    note='Requeued: editorial gaps remain'
  from private.research_stage_rows() a
  where a.id=q.record_id and q.status='done' and q.attempts<5 and q.updated_at<now()-interval '1 day'
    and a.stage in (2,3) and a.stage4_blockers && array['summary_missing','author_or_organisation_missing',
      'publication_year_missing','topics_missing','current_field_evidence_required'];
  update private.research_editorial_queue set status='queued',held_reason=null,run_id=null,claimed_until=null,updated_at=now(),
    note='Requeued after evidence was unreachable'
  where status='held' and held_reason like 'evidence unreachable%' and attempts<3 and updated_at<now()-interval '3 days';
  get diagnostics requeued = row_count;
  return jsonb_build_object('upserted',added,'requeued',requeued,
    'queued',(select count(*) from private.research_editorial_queue where status='queued'));
end;
$fn$;

create or replace function private.research_editorial_claim(p_limit integer, p_reviewer text) returns jsonb
language plpgsql set search_path='' as $fn$
declare v_run uuid; v_ids text[];
begin
  if nullif(btrim(p_reviewer),'') is null then raise exception 'reviewer required'; end if;
  update private.research_editorial_runs set finished_at=now(),note=coalesce(note||' ','')||'lease expired'
  where finished_at is null and lease_until<now();
  insert into private.research_editorial_runs(lease_until,reviewer) values (now()+interval '45 minutes',btrim(p_reviewer))
  returning id into v_run;
  with picked as (
    select q.record_id from private.research_editorial_queue q
    where q.status='queued' or (q.status='claimed' and q.claimed_until<now())
    order by q.priority,q.record_id limit greatest(1,least(coalesce(p_limit,25),50))
    for update skip locked
  ), claimed as (
    update private.research_editorial_queue q set status='claimed',run_id=v_run,
      claimed_until=now()+interval '45 minutes',attempts=q.attempts+1,updated_at=now(),
      claim_fingerprint=(select md5((to_jsonb(r)-'search_vector')::text) from public.research_records r where r.id=q.record_id)
    from picked p where q.record_id=p.record_id
    returning q.record_id
  ) select array_agg(c.record_id order by c.record_id) into v_ids from claimed c;
  update private.research_editorial_runs set claimed=coalesce(cardinality(v_ids),0) where id=v_run;
  return jsonb_build_object('run',v_run,'ids',coalesce(to_jsonb(v_ids),'[]'::jsonb));
end;
$fn$;

-- Applies one run's results. Each item: {id, fingerprint?, hold?, summary?, summary_mode?, replace_reason?,
-- authors?, year?, tags?, evidence:{title,authors,year,source,summary,tags,url}}. Values are only filled
-- where the field is missing or a placeholder; a non-empty summary is replaced only with a stated reason.
create or replace function private.research_editorial_submit(p_run uuid, p_items jsonb) returns jsonb
language plpgsql set search_path='' as $fn$
declare
  v_run private.research_editorial_runs;
  item jsonb; rec public.research_records; q private.research_editorial_queue;
  fp text; new_fp text; v_reviewer text;
  new_summary text; new_authors text; new_year integer; new_tags text[];
  f text; ev text; actions jsonb; old_values jsonb; reviews jsonb := '{}'::jsonb; outcome jsonb;
  n_written integer:=0; n_filled integer:=0; n_held integer:=0; n_stale integer:=0; n_skipped integer:=0; n_s4 integer:=0;
  fields constant text[] := array['title','authors','year','source','summary','tags','url'];
begin
  select * into v_run from private.research_editorial_runs where id=p_run and finished_at is null and lease_until>now() for update;
  if v_run.id is null then raise exception 'run % is not active', p_run; end if;
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items)>50 then
    raise exception 'items must be an array of at most 50'; end if;
  v_reviewer := v_run.reviewer;
  perform pg_advisory_xact_lock(68130921);  -- same order as research_stage_apply and the runner
  for item in select value from jsonb_array_elements(p_items) loop
    select * into q from private.research_editorial_queue where record_id=item->>'id' for update;
    if q.record_id is null or q.status<>'claimed' or q.run_id is distinct from p_run then n_skipped:=n_skipped+1; continue; end if;
    select * into rec from public.research_records where id=q.record_id for update;
    fp := md5((to_jsonb(rec)-'search_vector')::text);
    -- The record must be unchanged since it was claimed (and match the caller's copy, if supplied).
    if fp is distinct from q.claim_fingerprint or (item ? 'fingerprint' and item->>'fingerprint' is distinct from fp) then
      update private.research_editorial_queue set status='queued',run_id=null,claimed_until=null,updated_at=now(),
        note='Record changed after claim; re-queued' where record_id=q.record_id;
      n_stale:=n_stale+1; continue;
    end if;
    if nullif(btrim(item->>'hold'),'') is not null then
      update private.research_editorial_queue set status='held',held_reason=left(btrim(item->>'hold'),300),
        claimed_until=null,updated_at=now() where record_id=q.record_id;
      n_held:=n_held+1; continue;
    end if;
    actions := '{}'::jsonb;
    -- Summary: original 1-2 sentence signposting text, no markup or links.
    new_summary := nullif(btrim(item->>'summary'),'');
    if new_summary is not null then
      if length(new_summary) not between 60 and 420
         or new_summary ~ '(https?://|www\.|[#*_`|<>\[\]{}])'
         or (select count(*) from regexp_matches(new_summary,'[.!?](\s|$)','g')) not between 1 and 3
         or public.research_clean_summary(new_summary)=''
         or new_summary ~* '(stage [0-9]|inventory record|placeholder|lorem ipsum)' then
        raise exception 'summary for % fails the editorial checks', q.record_id;
      end if;
      if coalesce(public.research_clean_summary(rec.summary),'')<>'' then
        if item->>'replace_reason' is null or item->>'replace_reason' not in ('copied_abstract','page_capture','not_descriptive','inaccurate') then
          raise exception 'summary for % already exists; a replace_reason is required', q.record_id;
        end if;
        if private.research_shares_run(new_summary, rec.summary) then
          raise exception 'summary for % repeats ten or more consecutive words of the summary it replaces', q.record_id;
        end if;
        actions := actions||jsonb_build_object('summary','replaced');
      else
        actions := actions||jsonb_build_object('summary','written');
      end if;
    end if;
    new_authors := nullif(btrim(item->>'authors'),'');
    if new_authors is not null then
      if not private.research_author_fillable(rec.authors) then raise exception 'authors for % are already recorded', q.record_id; end if;
      if private.research_author_missing(new_authors) or length(new_authors)>1200
         or new_authors ~ '(https?://|www\.|[<>{}\[\]|`*#])' then raise exception 'authors for % are not usable', q.record_id; end if;
      actions := actions||jsonb_build_object('authors','filled');
    end if;
    new_year := (item->>'year')::integer;
    if new_year is not null then
      if rec.year is not null then raise exception 'year for % is already recorded', q.record_id; end if;
      if new_year not between 1800 and extract(year from now())::int+1 then raise exception 'year for % is out of range', q.record_id; end if;
      actions := actions||jsonb_build_object('year','filled');
    end if;
    if jsonb_typeof(item->'tags')='array' and jsonb_array_length(item->'tags')>0 then
      if exists(select from unnest(rec.tags) t where btrim(t)<>'') then raise exception 'tags for % are already recorded', q.record_id; end if;
      select array_agg(distinct btrim(t)) into new_tags from jsonb_array_elements_text(item->'tags') t;
      if cardinality(new_tags)>6 or exists(select from unnest(new_tags) t where length(t) not between 3 and 60
           or t ~ '(https?://|www\.|[<>{}\[\]|`*#])') then
        raise exception 'tags for % are not usable', q.record_id; end if;
      actions := actions||jsonb_build_object('tags','filled');
    end if;
    -- Every field needs an evidence URL; a changed field must cite the page it was taken from.
    foreach f in array fields loop
      ev := item#>>array['evidence',f];
      if ev is null or ev !~ '^https?://[^[:space:]/]+' or length(ev)>2048 then
        raise exception 'evidence URL missing for % / %', q.record_id, f; end if;
    end loop;
    old_values := jsonb_build_object('summary',rec.summary,'authors',rec.authors,'year',rec.year::text,'tags',array_to_string(rec.tags,'; '));
    update public.research_records set
      summary=coalesce(new_summary,summary), authors=coalesce(new_authors,authors),
      year=coalesce(new_year,year), tags=coalesce(new_tags,tags)
    where id=q.record_id and (new_summary is not null or new_authors is not null or new_year is not null or new_tags is not null)
    returning * into rec;
    select * into rec from public.research_records where id=q.record_id;
    new_fp := md5((to_jsonb(rec)-'search_vector')::text);
    foreach f in array fields loop
      insert into private.research_field_evidence(record_id,field,action,evidence_url,record_fingerprint,reviewer,run_id,
        previous_value,note)
      values (q.record_id,f,coalesce(actions->>f,'confirmed'),item#>>array['evidence',f],new_fp,v_reviewer,p_run,
        case when actions ? f then old_values->>f end, case when f='summary' then item->>'replace_reason' end);
    end loop;
    if actions ? 'summary' then n_written:=n_written+1; end if;
    n_filled := n_filled + (select count(*) from jsonb_object_keys(actions) k where k<>'summary');
    reviews := reviews||jsonb_build_object(q.record_id,jsonb_build_object('fingerprint',new_fp,'reviewer',v_reviewer,
      'evidence',item->'evidence'));
    update private.research_editorial_queue set status='done',claimed_until=null,held_reason=null,updated_at=now(),
      note='Fields evidenced'||case when actions<>'{}'::jsonb then ': '||(select string_agg(key||' '||value,', ') from jsonb_each_text(actions)) else '' end
    where record_id=q.record_id;
  end loop;
  -- Record Stage 4 evidence (no final sign-off) for every reviewed record that now passes the gates.
  if reviews<>'{}'::jsonb then
    outcome := private.research_stage_apply(reviews);
    n_s4 := coalesce((outcome->>'stage4_recorded')::int,0);
  end if;
  update private.research_editorial_runs set written=written+n_written,filled=filled+n_filled,held=held+n_held,
    stale=stale+n_stale,stage4_recorded=stage4_recorded+n_s4 where id=p_run;
  return jsonb_build_object('written',n_written,'filled',n_filled,'held',n_held,'stale',n_stale,
    'skipped',n_skipped,'stage4_recorded',n_s4);
end;
$fn$;

-- Stage 5: the caller supplies the live search result and a link check from the last seven days.
-- Reviewer evidence is the record's current Stage 4 review; nothing is invented here, and the gates
-- (open issues, duplicates, search index, fingerprint) are re-checked by research_stage_apply.
create or replace function private.research_editorial_signoff(p_run uuid, p_items jsonb) returns jsonb
language plpgsql set search_path='' as $fn$
declare v_run private.research_editorial_runs; v_reviews jsonb; v_outcome jsonb;
begin
  select * into v_run from private.research_editorial_runs where id=p_run and finished_at is null and lease_until>now();
  if v_run.id is null then raise exception 'run % is not active', p_run; end if;
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items)>100 then
    raise exception 'items must be an array of at most 100'; end if;
  with wanted as (
    select w.value->>'id' id, w.value item from jsonb_array_elements(p_items) w
    where w.value->>'live_found'='true' and (w.value->>'link_verified_at')::timestamptz<=now()
      and (w.value->>'link_verified_at')::timestamptz>=now()-interval '7 days'
  ), assessed as (
    select a.record_id,a.checks from private.enrichment_dashboard_assurance() a where a.record_id in (select id from wanted)
  )
  -- duplicate_reviewed is asserted here because the gates themselves refuse Stage 5 while any duplicate
  -- group containing the record is unreviewed; relevance evidence is the page the summary was written from.
  select jsonb_object_agg(w.id,((a.checks->'stage4_review')-'final')||jsonb_build_object(
      'final',jsonb_build_object('relevance_evidence',a.checks#>>'{stage4_review,evidence,summary}',
        'checked_url',r.url,'link_verified_at',w.item->>'link_verified_at','duplicate_reviewed',true),
      'live_found',true))
  into v_reviews
  from wanted w join public.research_records r on r.id=w.id join assessed a on a.record_id=w.id
  where a.checks#>>'{stage4_review,fingerprint}'=md5((to_jsonb(r)-'search_vector')::text)
    and w.item->>'fingerprint'=md5((to_jsonb(r)-'search_vector')::text)
    and a.checks#>>'{stage4_review,evidence,summary}' ~ '^https?://[^[:space:]/]+'
    and w.item->>'checked_url'=r.url;
  if v_reviews is null then return jsonb_build_object('stage5_signed_off',0,'considered',jsonb_array_length(p_items)); end if;
  v_outcome := private.research_stage_apply(v_reviews);
  update private.research_editorial_runs set signed_off=signed_off+coalesce((v_outcome->>'stage5_signed_off')::int,0) where id=p_run;
  return v_outcome||jsonb_build_object('considered',jsonb_array_length(p_items));
end;
$fn$;

create or replace function private.research_editorial_finish(p_run uuid, p_note text default null) returns jsonb
language plpgsql set search_path='' as $fn$
declare v_run private.research_editorial_runs;
begin
  update private.research_editorial_queue set status='queued',run_id=null,claimed_until=null,updated_at=now(),
    note='Released unfinished at end of run' where run_id=p_run and status='claimed';
  update private.research_editorial_runs set finished_at=now(),note=left(p_note,500) where id=p_run and finished_at is null
  returning * into v_run;
  perform private.refresh_research_stage_state('editorial run '||p_run::text);
  return to_jsonb(v_run);
end;
$fn$;
revoke all on function private.research_author_missing(text), private.research_author_fillable(text),
  private.research_words(text), private.research_shares_run(text,text), private.research_editorial_seed(),
  private.research_editorial_claim(integer,text), private.research_editorial_submit(uuid,jsonb),
  private.research_editorial_signoff(uuid,jsonb), private.research_editorial_finish(uuid,text),
  private.refuse_evidence_change() from public, anon, authenticated;

create or replace function private.research_stage_report() returns jsonb
language plpgsql stable set search_path='' as $fn$
declare result jsonb;
begin
  if to_regclass('private.verification_items') is null then return null; end if;
  execute $q$
  with latest as (select * from private.research_stage_snapshots order by taken_at desc limit 1),
  first as (select min(taken_at) since from private.research_stage_snapshots),
  day as (select * from private.research_stage_transitions where changed_at>now()-interval '24 hours'),
  items as (select i.record_id from private.verification_items i
    where i.assessed_at>now()-interval '24 hours' and i.selected_reason='reviewed research stage evidence'),
  editorial as (select * from private.research_editorial_runs where started_at>now()-interval '24 hours')
  select jsonb_build_object(
    'takenAt',l.taken_at,'reliableSince',f.since,'total',l.total,'counts',l.counts,'blockers',l.blockers,
    'last24h',jsonb_build_object(
      'advancedRecords',(select count(distinct record_id) from day where to_stage>coalesce(from_stage,0)),
      'regressedRecords',(select count(distinct record_id) from day where to_stage<from_stage),
      'reachedStage5',(select count(distinct record_id) from day where to_stage=5 and coalesce(from_stage,0)<5),
      'transitions',(select count(*) from day),
      'reviewAttempts',(select count(*) from items),
      'reviewedRecords',(select count(distinct record_id) from items),
      'editorialRuns',(select count(*) from editorial),
      'summariesWritten',(select coalesce(sum(written),0) from editorial),
      'fieldsFilled',(select coalesce(sum(filled),0) from editorial),
      'heldBack',(select coalesce(sum(held),0) from editorial)),
    'byStage24h',(select coalesce(jsonb_object_agg(to_stage::text,n),'{}'::jsonb) from
      (select to_stage,count(distinct record_id) n from day where to_stage>coalesce(from_stage,0) group by to_stage) z),
    'editorialQueue',(select jsonb_object_agg(status,n) from (select status,count(*) n
      from private.research_editorial_queue group by status) q))
  from latest l cross join first f
  $q$ into result;
  return result;
end;
$fn$;
revoke all on function private.research_stage_report() from public, anon, authenticated;

-- 6. Admin-only dashboard data: the existing report plus the stage panel (same admin check).
create or replace function public.directory_live_enrichment(p_actor uuid,p_session uuid,p_assurance text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
  perform public.directory_api('admin_analytics','{}',p_actor,p_session,p_assurance);
  return private.live_enrichment_report()||jsonb_build_object('stages',private.research_stage_report());
end;
$$;
revoke all on function public.directory_live_enrichment(uuid,uuid,text) from public, anon, authenticated;
grant execute on function public.directory_live_enrichment(uuid,uuid,text) to service_role;

-- 7. Hourly stage snapshot (minute 40, clear of the :50 assurance and :55 enrichment jobs).
do $$
begin
  if to_regclass('cron.job') is not null then
    execute $q$select cron.schedule('id-ebp-research-stage-refresh','40 * * * *','select private.refresh_research_stage_state()')
      where not exists (select from cron.job where jobname='id-ebp-research-stage-refresh')$q$;
  end if;
end $$;
